-- Create mini_cust_info table
CREATE TABLE IF NOT EXISTS roadsure_final.mini_cust_info (
  cust_name  TEXT NOT NULL,
  cust_email TEXT,
  cust_phone TEXT,
  session_id TEXT NOT NULL
);

-- Helpful index for lookups by session_id
CREATE INDEX IF NOT EXISTS idx_mini_cust_info_session
  ON roadsure_final.mini_cust_info (session_id);

-- Ensure UUID generator is available (safe to re-run)
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Add UUID column with default
ALTER TABLE roadsure_final.mini_cust_info
  ADD COLUMN cust_id UUID DEFAULT gen_random_uuid();

-- Make it NOT NULL and primary key
ALTER TABLE roadsure_final.mini_cust_info
  ALTER COLUMN cust_id SET NOT NULL;

ALTER TABLE roadsure_final.mini_cust_info
  ADD CONSTRAINT mini_cust_info_pkey PRIMARY KEY (cust_id);

-- Create the registry table to store {column: type} per table
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS roadsure_final.total_schema_table (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  schema_name TEXT NOT NULL,
  table_name  TEXT NOT NULL,
  columns     JSONB NOT NULL,   -- e.g., { "cust_name": "text", "session_id": "text" }
  captured_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uq_total_schema UNIQUE (schema_name, table_name)
);

CREATE INDEX IF NOT EXISTS idx_total_schema_tbl
  ON roadsure_final.total_schema_table (schema_name, table_name);

SELECT *
FROM roadsure_final.quote_register
ORDER BY created_at DESC;
